package bridge

import (
	"bytes"
	"encoding/json"
	"os"
	"testing"
)

// addonPanel is testdata/shot_panel_blocks.json, generated by the addon (tools/lua/gen_shot_fixture.lua):
// the frames as the addon composes them and the colour of every block of each row.
type addonPanel struct {
	BlockPx  int       `json:"blockPx"`
	W        int       `json:"W"`
	H        int       `json:"H"`
	N        int       `json:"N"`
	ShotID   int       `json:"shotId"`
	DataRows int       `json:"dataRows"`
	Data     []int     `json:"data"`
	Frames   [][]int   `json:"frames"`
	Blocks   [][][]int `json:"blocks"`
}

func loadAddonPanel(t *testing.T) addonPanel {
	t.Helper()
	raw, err := os.ReadFile("../../testdata/shot_panel_blocks.json")
	if err != nil {
		t.Fatal(err)
	}
	var p addonPanel
	if err := json.Unmarshal(raw, &p); err != nil {
		t.Fatalf("fixture: %v", err)
	}
	return p
}

func bytesOf(ints []int) []byte {
	out := make([]byte, len(ints))
	for i, v := range ints {
		out[i] = byte(v)
	}
	return out
}

// TestAddonPanelFixture checks the encoding against the addon: the frame bytes parse as version 5
// frames of the shot, the blocks it paints are the blocks BlocksV31 gives, and a panel drawn from
// them decodes to the payload the addon started from.
func TestAddonPanelFixture(t *testing.T) {
	p := loadAddonPanel(t)
	if len(p.Frames) != p.DataRows+1 {
		t.Fatalf("fixture has %d frames, want %d data rows and an end row", len(p.Frames), p.DataRows)
	}
	var rows [][]byte
	for r, fr := range p.Frames {
		frame := bytesOf(fr)
		f, err := ParseFrameV5(frame)
		if err != nil {
			t.Fatalf("row %d: %v", r, err)
		}
		if int(f.ShotID) != p.ShotID || f.N != p.N {
			t.Fatalf("row %d: shot %d with %d blocks, want %d and %d", r, f.ShotID, f.N, p.ShotID, p.N)
		}
		want := BlocksV31(frame, p.N)
		for b, blk := range p.Blocks[r] {
			if want[b] != [3]byte{byte(blk[0]), byte(blk[1]), byte(blk[2])} {
				t.Fatalf("row %d block %d: addon paints %v, BlocksV31 gives %v", r, b, blk, want[b])
			}
		}
		rows = append(rows, frame)
	}
	end, err := ParseFrameV5(rows[len(rows)-1])
	if err != nil || !IsEndFrame(end) || int(end.ChunkCount) != p.DataRows {
		t.Fatalf("end row: %+v, err %v", end, err)
	}

	// The addon's blocks at its own block size, as a panel image.
	img := RenderPanel(rows, p.N, PanelOptions{BlockPx: p.BlockPx, Width: p.W, Height: p.H})
	res, err := DecodePanel(img)
	if err != nil {
		t.Fatalf("DecodePanel: %v", err)
	}
	if !res.Complete || len(res.Frames) != len(rows) {
		t.Fatalf("panel: complete %v, %d rows (stop %v)", res.Complete, len(res.Frames), res.Stop)
	}
	if got := reassemble(t, res.Frames); !bytes.Equal(got, bytesOf(p.Data)) {
		t.Fatalf("payload: got %d bytes, want %d", len(got), len(p.Data))
	}
}
